#include <bits/stdc++.h>
using namespace std;

int main() {
    int h, w;
    cin >> h >> w;
    vector<pair<int, int>> pieces;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            char c;
            cin >> c;
            if (c == 'o') {
                pieces.emplace_back(i, j);
            }
        }
    }
    const auto& [a, b] = pieces[0];
    const auto& [c, d] = pieces[1];
    cout << abs(a - c) + abs(b - d) << '\n';
    return 0;
}

h, w = map(int, input().split())
s = [input() for _ in range(h)]
pieces = []
for i in range(h):
  for j in range(w):
